cssText:
.stage { background: linear-gradient(180deg, var(--slide) 0%, var(--slide) 46%, var(--slide-low) 100%); }
.hud-h, .hud-end .t { font-variation-settings: "opsz" 72; }
.hud-series { font-family: var(--font-text); text-transform: uppercase; letter-spacing: .16em; font-weight: 600; }
.hud-counter .v, .hud-scale, .hud-badge { font-feature-settings: "tnum" 1; }
.hud-badge { letter-spacing: .01em; }
